function narrationDB(){return narrationWorkDB??=new Promise((resolve,reject)=>{const r=indexedDB.open('elleson-narration-work',1);r.onupgradeneeded=()=>{for(const name of ['drafts','sections','jobs'])r.result.createObjectStore(name,{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function narrationRecord(store,mode,action){const db=await narrationDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),r=action(tx.objectStore(store));let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Could not save voice work.'))})}
async function narrationHash(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].map(n=>n.toString(16).padStart(2,'0')).join('')}
function narrationDraftIdentity(context){return [context.project.projectId||context.project.scenes[0].id,context.scene.id,context.line.audioId||context.line.longVoiceGroupId?context.line.id:context.line.speakerId||'narrator'].join(':')}
function captureNarrationDraft(){if(!narrationDraftKey||!$('offlineVoiceDialog').open)return null;return{key:narrationDraftKey,base:narrationDraftBase,text:$('offlineVoiceText').value,voice:$('offlineVoiceChoice').value,speed:+$('offlineVoiceSpeed').value,delivery:$('offlineVoiceDelivery').value,phrases:$('phraseVoiceEnabled').checked?structuredClone(voicePhraseDraft):[],updated:Date.now()}}
function storeNarrationDraft(snapshot=captureNarrationDraft()){if(!snapshot)return narrationDraftWrites;const work=()=>narrationRecord('drafts','readwrite',s=>s.put(snapshot));narrationDraftWrites=narrationDraftWrites.then(work,work).catch(()=>{$('offlineVoiceStatus').textContent='Draft could not be saved. Keep a copy of your script before closing.'});return narrationDraftWrites}
function scheduleNarrationDraft(){clearTimeout(narrationDraftTimer);const snapshot=captureNarrationDraft();narrationDraftTimer=setTimeout(()=>storeNarrationDraft(snapshot),180);updateNarrationPlan()}
for(const id of ['offlineVoiceText','offlineVoiceChoice','offlineVoiceSpeed','offlineVoiceDelivery','phraseVoiceEnabled'])$(id).addEventListener(id==='offlineVoiceText'?'input':'change',scheduleNarrationDraft);
$('offlineVoiceDialog').addEventListener('close',()=>{clearTimeout(narrationDraftTimer);if(narrationDraftKey){const snapshot={key:narrationDraftKey,base:narrationDraftBase,text:$('offlineVoiceText').value,voice:$('offlineVoiceChoice').value,speed:+$('offlineVoiceSpeed').value,delivery:$('offlineVoiceDelivery').value,phrases:$('phraseVoiceEnabled').checked?structuredClone(voicePhraseDraft):[],updated:Date.now()};storeNarrationDraft(snapshot)}narrationDraftKey=null});
const narrationOptions=document.createElement('div');narrationOptions.innerHTML='<p id="narrationCapacity" class="note" role="status"></p><label><input id="narrationContinueVisuals" type="checkbox" checked> Continue the picture and characters into new scenes</label><label><input id="narrationAudioOnly" type="checkbox"> Generate audio only (save a WAV without adding scenes)</label>';$('voiceScriptLength').after(narrationOptions);
const sampleButton=storyButton('Hear 15-second sample',()=>offlineVoiceTask(previewNarrationSample));sampleButton.id='previewVoiceSample';$('previewOfflineVoice').before(sampleButton);
const sectionEditor=document.createElement('details');sectionEditor.id='narrationSectionEditor';sectionEditor.innerHTML='<summary>Edit one narration section</summary><p class="note">Change one paragraph or section. Completed sections are reused from this device; only changed text is generated again.</p><select id="narrationSectionChoice" aria-label="Narration section"></select><textarea id="narrationSectionText" rows="3" aria-label="Edited narration section"></textarea><button id="replaceNarrationSection">Preview section edit</button>';$('phraseVoicePanel').after(sectionEditor);
// Paragraph boundaries stay stable when an earlier paragraph changes length.
function narrationSections(text){const sections=[];const paragraphs=[...text.matchAll(/[^\n]+(?:\n(?!\n)[^\n]+)*/g)];for(const paragraph of paragraphs){let cursor=paragraph.index;for(const chunk of splitNarrationText(paragraph[0])){const leading=chunk.length-chunk.trimStart().length,clean=chunk.trim();if(clean)sections.push({text:clean,start:cursor+leading,end:cursor+chunk.trimEnd().length});cursor+=chunk.length}}return sections}
function narrationRequestSections(request){const phrases=request.phrases||[{text:request.text,speed:1,emphasis:'none',pause:0}];return phrases.flatMap((phrase,index)=>narrationSections(phrase.text).map((section,i,all)=>({...section,speed:phrase.speed,emphasis:phrase.emphasis,pause:i===all.length-1&&index<phrases.length-1?phrase.pause:0})))}
function narrationRoom(context=offlineVoiceContext){if(!context||context.project!==project)return{seconds:0,clips:0};const group=context.line.longVoiceGroupId,owned=ownedStoryVoice(context.line),old=tracks().filter(c=>group?c.longVoiceGroupId===group:c.id===owned?.id),slots=99-(tracks().length-old.length);let seconds=0,used=0;const si=project.scenes.indexOf(context.scene);for(let i=si;i<project.scenes.length&&used<slots;i++){const s=project.scenes[i],available=s.duration-(i===si?context.line.start:0),lines=storyLines(s).filter(l=>l!==context.line&&(!group||l.longVoiceGroupId!==group));if(lines.length>=200||available<=0)break;seconds+=available;used++}seconds+=Math.min(Math.max(0,slots-used),99-project.scenes.length)*60;return{seconds:Math.max(0,seconds),clips:slots}}
function estimateNarrationSeconds(request){const words=request.text.trim().split(/\s+/).length,pauses=(request.text.match(/[.!?]/g)||[]).length*.14;return(words/2.8+pauses)/(request.speed||1)+(request.phrases||[]).reduce((n,p)=>n+p.pause,0)}
function checkNarrationCapacity(request,duration,exact=false){if($('narrationAudioOnly').checked)return;const room=narrationRoom();if(room.clips<1)throw Error('There is no audio capacity left. Choose Generate audio only to save this narration as a WAV.');if(duration>room.seconds+(exact?.002:0))throw Error((exact?'This narration needs ':'Estimated narration is ')+Math.ceil(duration)+' seconds; the project has room for '+Math.floor(room.seconds)+' seconds. Shorten the script or choose Generate audio only to save a WAV.');}
function updateNarrationPlan(){const text=$('offlineVoiceText').value;narrationPlan=narrationSections(text);const list=$('narrationSectionChoice'),selected=Math.min(+list.value||0,Math.max(0,narrationPlan.length-1));list.replaceChildren();narrationPlan.forEach((section,i)=>{const option=document.createElement('option');option.value=i;option.textContent=(i+1)+'. '+section.text.slice(0,65);list.append(option)});list.value=String(selected);$('narrationSectionText').value=narrationPlan[selected]?.text||'';try{const request=offlineVoiceRequest(),estimate=estimateNarrationSeconds(request),room=narrationRoom();$('narrationCapacity').textContent='Estimated '+Math.ceil(estimate)+'s · project room '+Math.floor(room.seconds)+'s'+(estimate>room.seconds?' · may not fit; audio-only generation is available.':'. Duration varies with the voice.')}catch{$('narrationCapacity').textContent='Your script draft is saved automatically on this device.'}}
$('narrationSectionChoice').onchange=()=>{$('narrationSectionText').value=narrationPlan[+$('narrationSectionChoice').value]?.text||''};
$('replaceNarrationSection').onclick=async()=>{if(offlineVoiceBusy)return;const part=narrationPlan[+$('narrationSectionChoice').value],replacement=$('narrationSectionText').value.trim();if(!part||!replacement)return $('offlineVoiceStatus').textContent='Write the replacement words first.';const text=$('offlineVoiceText');text.value=text.value.slice(0,part.start)+replacement+text.value.slice(part.end);$('phraseVoiceEnabled').checked=false;scheduleNarrationDraft();if(offlineVoiceContext?.line.audioId)await $('addOfflineVoice').onclick();else await offlineVoiceTask(()=>synthesizeOfflineVoice())};
function matchNarrationLoudness(source){const buffer=new AudioBuffer({numberOfChannels:source.numberOfChannels,length:source.length,sampleRate:source.sampleRate});let energy=0,count=0,peak=0;for(let ch=0;ch<source.numberOfChannels;ch++){const data=source.getChannelData(ch);for(let i=0;i<data.length;i++){const v=data[i];peak=Math.max(peak,Math.abs(v));}}for(let ch=0;ch<source.numberOfChannels;ch++)for(const v of source.getChannelData(ch))if(Math.abs(v)>Math.max(.00005,peak*.1)){energy+=v*v;count++}const activeRMS=Math.sqrt(energy/Math.max(1,count)),gain=activeRMS>.0001?Math.min(4,.11/activeRMS,.96/Math.max(.0001,peak)):1;for(let ch=0;ch<source.numberOfChannels;ch++){const input=source.getChannelData(ch),output=buffer.getChannelData(ch);for(let i=0;i<input.length;i++)output[i]=input[i]*gain}return buffer}
async function trimNarrationCache(){const all=await narrationRecord('sections','readonly',s=>s.getAll());let bytes=all.reduce((n,s)=>n+s.audio.size,0);for(const entry of all.sort((a,b)=>a.updated-b.updated)){if(bytes<=384*1024*1024)break;await narrationRecord('sections','readwrite',s=>s.delete(entry.key));bytes-=entry.audio.size}}
generateNarrationSection=async function(settings){if(voiceGenerationCancelled)throw Error('Voice generation stopped. Completed sections are saved; preview again to resume.');const identity={...settings};delete identity.previousText;delete identity.nextText;const serialized=JSON.stringify(identity),key=await narrationHash(serialized);let buffer=sectionVoiceCache.get(key);if(buffer)return buffer;const saved=await narrationRecord('sections','readonly',s=>s.get(key));if(saved?.settings===serialized){buffer=await decodeFile(saved.audio);saved.updated=Date.now();await narrationRecord('sections','readwrite',s=>s.put(saved))}else{const response=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(settings)});if(!response.ok)throw Error((await response.json()).error||'Voice generation failed.');const audio=await response.blob();buffer=await decodeFile(audio);if(!Number.isFinite(buffer.duration)||buffer.duration<=0)throw Error('The voice engine returned empty audio.');try{await narrationRecord('sections','readwrite',s=>s.put({key,settings:serialized,audio,updated:Date.now()}));await trimNarrationCache()}catch{$('offlineVoiceStatus').textContent='Audio is ready, but recovery storage is full. Save the WAV before closing.'}}sectionVoiceCache.set(key,buffer);while(sectionVoiceCache.size>32)sectionVoiceCache.delete(sectionVoiceCache.keys().next().value);return buffer};
function narrationSectionSettings(request,section,sections,index){const online=request.voice.startsWith('elevenlabs:');return{text:section.text,voice:request.voice,speed:narrationVoiceSpeed(request.speed*section.speed*(section.emphasis==='strong'?.96:1),request.voice),delivery:request.delivery,...(request.pronunciations?{pronunciations:request.pronunciations}:{}),...(online?{previousText:sections.slice(0,index).map(s=>s.text).join(' ').slice(-1000),nextText:sections.slice(index+1).map(s=>s.text).join(' ').slice(0,1000)}:{})}}
synthesizeOfflineVoice=async function(){const request=offlineVoiceRequest(),key=JSON.stringify(request);if(offlineVoiceCache?.key===key){$('offlineVoiceAudio').src=offlineVoiceCache.src;$('offlineVoiceAudio').hidden=false;return offlineVoiceCache}checkNarrationCapacity(request,estimateNarrationSeconds(request));await storeNarrationDraft();const sections=narrationRequestSections(request),generated=[],jobKey=await narrationHash(key),job={key:jobKey,request,completed:0,total:sections.length,updated:Date.now(),status:'generating'};voiceGenerationCancelled=false;$('cancelVoiceGeneration').hidden=false;$('cancelVoiceGeneration').disabled=false;try{for(const [i,section]of sections.entries()){if(voiceGenerationCancelled)throw Error('Voice generation stopped. Completed sections are saved; preview again to resume.');$('offlineVoiceStatus').textContent=(request.voice.startsWith('elevenlabs:')?'Generating with ElevenLabs':'Generating on your PC')+' · section '+(i+1)+' / '+sections.length+' · completed sections are recoverable';const raw=await generateNarrationSection(narrationSectionSettings(request,section,sections,i));if(voiceGenerationCancelled)throw Error('Voice generation stopped. Completed sections are saved; preview again to resume.');generated.push({buffer:matchNarrationLoudness(raw),gain:section.emphasis==='strong'?1.18:section.emphasis==='gentle'?.82:1,pause:section.pause});job.completed=i+1;job.updated=Date.now();await narrationRecord('jobs','readwrite',s=>s.put(job));checkNarrationCapacity(request,generated.reduce((n,p)=>n+p.buffer.duration+p.pause,0),true)}const buffer=joinNarrationAudio(generated),src=await dataURL(wavBlob(buffer));offlineVoiceCache={key,request,buffer,src};narrationLastGeneration={sections:sections.map(s=>s.text),duration:buffer.duration};voiceTakePreviewId=null;$('offlineVoiceAudio').src=src;$('offlineVoiceAudio').hidden=false;$('offlineVoiceStatus').textContent='Ready · '+buffer.duration.toFixed(1)+' seconds. Completed sections are saved for edits and recovery.';job.status='complete';await narrationRecord('jobs','readwrite',s=>s.put(job));return offlineVoiceCache}catch(e){job.status=voiceGenerationCancelled?'stopped':'interrupted';job.updated=Date.now();await narrationRecord('jobs','readwrite',s=>s.put(job)).catch(()=>{});throw e}finally{$('cancelVoiceGeneration').hidden=true}};
async function previewNarrationSample(){const full=offlineVoiceRequest(),words=full.text.match(/\S+\s*/g)||[],text=splitNarrationText(words.slice(0,34).join(''))[0].trim(),request={...full,text};delete request.phrases;voiceGenerationCancelled=false;const section={text,speed:1,emphasis:'none'};$('offlineVoiceStatus').textContent='Creating a short voice sample…';const raw=await generateNarrationSection(narrationSectionSettings(request,section,[section],0)),normalized=matchNarrationLoudness(raw),buffer=normalized.duration>15?sliceNarrationBuffer(normalized,0,15*normalized.sampleRate):normalized;$('offlineVoiceAudio').src=await dataURL(wavBlob(buffer));$('offlineVoiceAudio').hidden=false;await $('offlineVoiceAudio').play().catch(()=>{});$('offlineVoiceStatus').textContent='Sample · '+buffer.duration.toFixed(1)+' seconds. Add to timeline will generate the complete script.'}
const openBeforeNarrationWork=openOfflineVoice;openOfflineVoice=async function(line){await openBeforeNarrationWork(line);if(!offlineVoiceReady||!$('offlineVoiceDialog').open)return;const context=offlineVoiceContext;narrationDraftKey=narrationDraftIdentity(context);narrationDraftBase=context.line.text;const draft=await narrationRecord('drafts','readonly',s=>s.get(narrationDraftKey));if(offlineVoiceContext!==context)return;if(draft&&draft.base===narrationDraftBase){$('offlineVoiceText').value=draft.text;if(offlineVoices.some(v=>v.id===draft.voice))$('offlineVoiceChoice').value=draft.voice;const speed=$('offlineVoiceSpeed');if(![...speed.options].some(o=>+o.value===draft.speed)){const option=document.createElement('option');option.value=String(draft.speed);option.textContent='Saved pace · '+draft.speed;speed.append(option)}speed.value=String(draft.speed);$('offlineVoiceDelivery').value=draft.delivery;voicePhraseDraft=structuredClone(draft.phrases||[]);$('phraseVoiceEnabled').checked=!!voicePhraseDraft.length;renderVoicePhrases();$('offlineVoiceStatus').textContent='Your saved voice draft was restored. Completed sections will be reused.'}$('replaceNarrationSection').textContent=context.line.audioId?'Replace section in timeline':'Preview section edit';$('narrationAudioOnly').checked=false;updateNarrationPlan()};
const addBeforeNarrationWork=$('addOfflineVoice').onclick;$('addOfflineVoice').onclick=async()=>{if($('narrationAudioOnly').checked)return $('offlineVoiceStatus').textContent='Audio-only mode is selected. Use Save audio, or clear audio-only mode to add to the timeline.';await storeNarrationDraft();const key=narrationDraftKey;await addBeforeNarrationWork();if(!$('offlineVoiceDialog').open&&offlineVoiceContext?.line.audioId){narrationDraftKey=null;await narrationDraftWrites;await narrationRecord('drafts','readwrite',s=>s.delete(key)).catch(()=>{})}};
